1	import { Logger } from '../logger';
2	import type { TrendAnalysis } from '../schema/types';
3	
4	const log = new Logger('VISUALIZE');
5	
6	// =============================================================================
7	// Types
8	// =============================================================================
9	
10	export interface SvgOptions {
11	  width?: number;
12	  height?: number;
13	  colorScheme?: 'default' | 'colorblind';
14	}
15	
16	// =============================================================================
17	// Color palettes
18	// =============================================================================
19	
20	const BARS_DEFAULT = ['#3B82F6', '#6366F1', '#8B5CF6'];
21	const BARS_COLORBLIND = ['#0077BB', '#EE7733', '#009988', '#CC3311', '#33BBEE', '#AA3377', '#BBBBBB'];
22	const SENTIMENT_COLORS_DEFAULT: Record<string, string> = {
23	  positive: '#059669',
24	  neutral: '#6B7280',
25	  negative: '#DC2626',
26	};
27	const SENTIMENT_COLORS_COLORBLIND: Record<string, string> = {
28	  positive: '#0077BB',
29	  neutral: '#BBBBBB',
30	  negative: '#CC3311',
31	};
32	const SENTIMENT_LABELS: Record<string, string> = {
33	  positive: '正面',
34	  neutral: '中性',
35	  negative: '负面',
36	};
37	
38	// =============================================================================
39	// Helpers
40	// =============================================================================
41	
42	function wrapSvg(content: string, w: number, h: number): string {
43	  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${w} ${h}">
44	  <style>
45	    .title { font-family: system-ui, -apple-system, sans-serif; font-size: 18px; font-weight: bold; fill: #111827; }
46	    .label { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #374151; }
47	    .value { font-family: system-ui, -apple-system, sans-serif; font-size: 13px; fill: #6B7280; }
48	    .note { font-family: system-ui, -apple-system, sans-serif; font-size: 11px; fill: #9CA3AF; }
49	    .grid { stroke: #E5E7EB; stroke-width: 1; stroke-dasharray: 4 4; }
50	    .axis { stroke: #D1D5DB; stroke-width: 2; }
51	  </style>
52	${content}
53	</svg>`;
54	}
55	
56	function truncate(s: string, maxLen: number): string {
57	  if (s.length <= maxLen) return s;
58	  return s.slice(0, maxLen - 1) + '…';
59	}
60	
61	/**
62	 * Compute a polar-to-cartesian point.
63	 */
64	function polarPoint(cx: number, cy: number, r: number, angleDeg: number): { x: number; y: number } {
65	  const rad = (angleDeg * Math.PI) / 180;
66	  return { x: cx + r * Math.cos(rad), y: cy + r * Math.sin(rad) };
67	}
68	
69	/**
70	 * Build an SVG arc path for a donut segment (inner to outer).
71	 * Angles in degrees, measured clockwise from the positive x-axis.
72	 */
73	function donutArcPath(
74	  cx: number, cy: number,
75	  innerR: number, outerR: number,
76	  startDeg: number, endDeg: number,
77	): string {
78	  // Clamp angles
79	  let start = startDeg;
80	  let end = endDeg;
81	  // Normalize to 0-360
82	  const sweep = end - start;
83	
84	  const outerStart = polarPoint(cx, cy, outerR, start);
85	  const outerEnd = polarPoint(cx, cy, outerR, end);
86	  const innerStart = polarPoint(cx, cy, innerR, start);
87	  const innerEnd = polarPoint(cx, cy, innerR, end);
88	
89	  const largeArc = sweep > 180 ? 1 : 0;
90	
91	  return [
92	    `M ${outerStart.x.toFixed(2)} ${outerStart.y.toFixed(2)}`,
93	    `A ${outerR} ${outerR} 0 ${largeArc} 1 ${outerEnd.x.toFixed(2)} ${outerEnd.y.toFixed(2)}`,
94	    `L ${innerEnd.x.toFixed(2)} ${innerEnd.y.toFixed(2)}`,
95	    `A ${innerR} ${innerR} 0 ${largeArc} 0 ${innerStart.x.toFixed(2)} ${innerStart.y.toFixed(2)}`,
96	    'Z',
97	  ].join(' ');
98	}
99	
100	// =============================================================================
101	// SvgGenerator class
102	// =============================================================================
103	
104	export class SvgGenerator {
105	  private readonly width: number;
106	  private readonly height: number;
107	  private readonly colorScheme: 'default' | 'colorblind';
108	
109	  constructor(options?: SvgOptions) {
110	    this.width = options?.width ?? 800;
111	    this.height = options?.height ?? 500;
112	    this.colorScheme = options?.colorScheme ?? 'default';
113	  }
114	
115	  // ---------------------------------------------------------------------------
116	  // Topic bar chart
117	  // ---------------------------------------------------------------------------
118	
119	  generateTopicBarChart(
120	    topicFrequency: Record<string, number>,
121	    date: string,
122	    topN = 10,
123	  ): string {
124	    log.info(`Generating topic bar chart for ${date} (topN=${topN})`);
125	
126	    const entries = Object.entries(topicFrequency)
127	      .sort((a, b) => b[1] - a[1])
128	      .slice(0, Math.max(1, topN)); // At least try to show 1
129	
130	    if (entries.length === 0) {
131	      // Empty state
132	      return this.emptySvg(`AI 话题热度 — ${date}`, '暂无话题数据', date);
133	    }
134	
135	    const maxVal = entries[0][1];
136	    const w = this.width;
137	    const h = this.height;
138	
139	    const barH = 30;
140	    const barGap = 5;
141	    const barAreaTop = 70;
142	    const barAreaBottom = 430;
143	    const maxBars = Math.min(entries.length, Math.floor((barAreaBottom - barAreaTop) / (barH + barGap)));
144	    const limited = entries.slice(0, maxBars);
145	
146	    const labelX = 200;
147	    const barStartX = 210;
148	    const maxBarWidth = 440;
149	    const valueX = 660;
150	
151	    const bars: string[] = [];
152	    const gridLines: string[] = [];
153	    const labels: string[] = [];
154	    const values: string[] = [];
155	
156	    // Grid lines (0%, 25%, 50%, 75%, 100%)
157	    for (const pct of [0, 0.25, 0.5, 0.75, 1]) {
158	      const gx = barStartX + maxBarWidth * pct;
159	      gridLines.push(`  <line class="grid" x1="${gx.toFixed(1)}" y1="${barAreaTop - 10}" x2="${gx.toFixed(1)}" y2="${barAreaTop + limited.length * (barH + barGap)}" />`);
160	    }
161	
162	    limited.forEach(([topic, count], i) => {
163	      const y = barAreaTop + i * (barH + barGap);
164	      const barWidth = maxVal > 0 ? (count / maxVal) * maxBarWidth : 0;
165	
166	      const colorIndex = this.colorScheme === 'colorblind'
167	        ? i % BARS_COLORBLIND.length
168	        : i % BARS_DEFAULT.length;
169	      const color = this.colorScheme === 'colorblind'
170	        ? BARS_COLORBLIND[colorIndex]
171	        : (i < 1 ? BARS_DEFAULT[0] : BARS_DEFAULT[Math.min(colorIndex, BARS_DEFAULT.length - 1)]);
172	
173	      // If colorblind, add pattern
174	      let rectExtra = '';
175	      if (this.colorScheme === 'colorblind') {
176	        rectExtra = ` fill="url(#cbBar${i})"`;
177	        // Add pattern definition (will be hoisted)
178	      } else {
179	        rectExtra = ` fill="${color}"`;
180	      }
181	
182	      labels.push(`  <text class="label" x="${labelX}" y="${y + barH / 2 + 4}" text-anchor="end">${truncate(topic, 15)}</text>`);
183	      bars.push(`  <rect role="bar" x="${barStartX}" y="${y}" width="${barWidth.toFixed(1)}" height="${barH}" rx="4"${rectExtra} />`);
184	      values.push(`  <text class="value" x="${valueX}" y="${y + barH / 2 + 4}">${count}</text>`);
185	    });
186	
187	    // Add pattern defs for colorblind
188	    let defs = '';
189	    if (this.colorScheme === 'colorblind') {
190	      const patterns = limited.map((_, i) => {
191	        const colorIndex = i % BARS_COLORBLIND.length;
192	        const color = BARS_COLORBLIND[colorIndex];
193	        return `  <pattern id="cbBar${i}" patternUnits="userSpaceOnUse" width="8" height="8">
194	    <rect width="8" height="8" fill="${color}" />
195	    <rect x="${i % 2 * 4}" y="${i % 2 * 4}" width="4" height="4" fill="#ffffff" opacity="0.4" />
196	  </pattern>`;
197	      });
198	      defs = `<defs>\n${patterns.join('\n')}\n  </defs>\n`;
199	    }
200	
201	    const svgContent = [
202	      defs,
203	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">AI 话题热度 Top-${limited.length} — ${date}</text>`,
204	      gridLines.join('\n'),
205	      labels.join('\n'),
206	      bars.join('\n'),
207	      values.join('\n'),
208	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
209	    ].join('\n');
210	
211	    return wrapSvg(svgContent, w, h);
212	  }
213	
214	  // ---------------------------------------------------------------------------
215	  // Sentiment donut chart
216	  // ---------------------------------------------------------------------------
217	
218	  generateSentimentDonut(
219	    sentimentDistribution: Record<string, number>,
220	    date: string,
221	  ): string {
222	    log.info(`Generating sentiment donut for ${date}`);
223	
224	    const entries = Object.entries(sentimentDistribution).filter(([, v]) => v > 0);
225	    const total = entries.reduce((s, [, v]) => s + v, 0);
226	
227	    const w = 600;
228	    const h = 500;
229	    const cx = 300;
230	    const cy = 250;
231	    const outerR = 120;
232	    const innerR = 60;
233	
234	    if (total === 0) {
235	      return this.emptySvg(`情感分布 — ${date}`, '暂无情感数据', date);
236	    }
237	
238	    const colors = this.colorScheme === 'colorblind'
239	      ? SENTIMENT_COLORS_COLORBLIND
240	      : SENTIMENT_COLORS_DEFAULT;
241	
242	    // Sort entries for consistent rendering: positive, neutral, negative
243	    const sorted = ['positive', 'neutral', 'negative']
244	      .filter((k) => entries.some(([key]) => key === k))
245	      .map((k) => [k, entries.find(([key]) => key === k)![1]] as [string, number]);
246	
247	    const paths: string[] = [];
248	    const legendItems: string[] = [];
249	
250	    // Start from the top (-90 degrees)
251	    let currentAngle = -90;
252	
253	    sorted.forEach(([key, value], idx) => {
254	      const pct = value / total;
255	      const sweepDeg = pct * 360;
256	      const endAngle = currentAngle + sweepDeg;
257	
258	      const color = colors[key] || '#6B7280';
259	
260	      // Add pattern defs for colorblind
261	      if (this.colorScheme === 'colorblind') {
262	        // Use texture via pattern
263	        paths.push(donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle));
264	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR - 2, outerR + 2, currentAngle, endAngle)}" fill="none" stroke="#333" stroke-width="1" />`);
265	      } else {
266	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle)}" fill="${color}" />`);
267	      }
268	
269	      // Legend
270	      const legendY = 150 + idx * 30;
271	      legendItems.push(`  <rect x="430" y="${legendY}" width="12" height="12" rx="2" fill="${color}" />`);
272	      legendItems.push(`  <text class="label" x="450" y="${legendY + 10}">${SENTIMENT_LABELS[key] || key} (${value})</text>`);
273	
274	      currentAngle = endAngle;
275	    });
276	
277	    const svgContent = [
278	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">情感分布 — ${date}</text>`,
279	      paths.join('\n'),
280	      `  <text class="value" x="${cx}" y="${cy - 8}" text-anchor="middle" font-size="24" font-weight="bold" fill="#111827">N=${total}</text>`,
281	      `  <text class="note" x="${cx}" y="${cy + 12}" text-anchor="middle" font-size="12">条</text>`,
282	      legendItems.join('\n'),
283	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
284	    ].join('\n');
285	
286	    return wrapSvg(svgContent, w, h);
287	  }
288	
289	  // ---------------------------------------------------------------------------
290	  // Trend radar chart
291	  // ---------------------------------------------------------------------------
292	
293	  generateTrendRadar(trends: TrendAnalysis, date: string): string {
294	    log.info(`Generating trend radar for ${date}`);
295	
296	    const w = 600;
297	    const h = 600;
298	    const cx = 300;
299	    const cy = 300;
300	    const axisLen = 200;
301	
302	    type TrendDimensionKey = 'technology' | 'application' | 'policy' | 'capital';
303	
304	    interface AxisDef {
305	      key: TrendDimensionKey;
306	      label: string;
307	      angleDeg: number; // clockwise from positive x-axis
308	    }
309	
310	    const axes: AxisDef[] = [
311	      { key: 'technology', label: '技术', angleDeg: -90 },
312	      { key: 'application', label: '应用', angleDeg: 0 },
313	      { key: 'policy', label: '政策', angleDeg: 90 },
314	      { key: 'capital', label: '资本', angleDeg: 180 },
315	    ];
316	
317	    // Helper to get data point on an axis
318	    const getPoint = (angleDeg: number, ratio: number) =>
319	      polarPoint(cx, cy, axisLen * ratio, angleDeg);
320	
321	    // Grid polygons (0.25, 0.5, 0.75, 1.0)
322	    const gridPolygons: string[] = [];
323	    for (const ratio of [0.25, 0.5, 0.75, 1.0]) {
324	      const pts = axes.map((a) => {
325	        const p = getPoint(a.angleDeg, ratio);
326	        return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
327	      });
328	      gridPolygons.push(`  <polygon class="grid" points="${pts.join(' ')}" fill="none" />`);
329	    }
330	
331	    // Axes lines from center to edge
332	    const axisLines: string[] = [];
333	    const axisLabels: string[] = [];
334	    axes.forEach((a) => {
335	      const tip = getPoint(a.angleDeg, 1.0);
336	      axisLines.push(`  <line class="axis" x1="${cx}" y1="${cy}" x2="${tip.x.toFixed(1)}" y2="${tip.y.toFixed(1)}" />`);
337	
338	      // Label at tip + offset
339	      const offset = 20;
340	      let lx = tip.x;
341	      let ly = tip.y;
342	      let anchor = 'middle';
343	      if (a.angleDeg === -90) { ly = tip.y - offset; anchor = 'middle'; }
344	      else if (a.angleDeg === 0) { lx = tip.x + offset; anchor = 'start'; }
345	      else if (a.angleDeg === 90) { ly = tip.y + offset; anchor = 'middle'; }
346	      else if (a.angleDeg === 180) { lx = tip.x - offset; anchor = 'end'; }
347	
348	      axisLabels.push(`  <text class="label" x="${lx.toFixed(1)}" y="${ly.toFixed(1)}" text-anchor="${anchor}" font-weight="bold" font-size="14">${a.label}</text>`);
349	
350	    });
351	
352	    // Data polygon
353	    const dataPoints = axes.map((a) => {
354	      const dim = trends[a.key];
355	      const conf = dim?.confidence ?? 0;
356	      const p = getPoint(a.angleDeg, conf);
357	      return `${p.x.toFixed(1)},${p.y.toFixed(1)}`;
358	    });
359	
360	    // Data value labels at each axis
361	    const dataLabels: string[] = [];
362	    axes.forEach((a) => {
363	      const dim = trends[a.key];
364	      const conf = dim?.confidence ?? 0;
365	      const p = getPoint(a.angleDeg, conf);
366	      const off = 12;
367	      const dx = a.angleDeg === 180 ? -off : a.angleDeg === 0 ? off : 0;
368	      const dy = a.angleDeg === -90 ? -off : a.angleDeg === 90 ? off : 0;
369	      const anchor = a.angleDeg === 180 ? 'end' : a.angleDeg === 0 ? 'start' : 'middle';
370	      dataLabels.push(`  <text class="value" x="${(p.x + dx).toFixed(1)}" y="${(p.y + dy).toFixed(1)}" text-anchor="${anchor}" font-size="13" font-weight="bold" fill="#3B82F6">${conf.toFixed(2)}</text>`);
371	    });
372	
373	    const svgContent = [
374	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">四维趋势雷达 — ${date}</text>`,
375	      gridPolygons.join('\n'),
376	      axisLines.join('\n'),
377	      axisLabels.join('\n'),
378	      `  <polygon points="${dataPoints.join(' ')}" fill="rgba(59, 130, 246, 0.2)" stroke="#3B82F6" stroke-width="2" />`,
379	      dataLabels.join('\n'),
380	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
381	    ].join('\n');
382	
383	    return wrapSvg(svgContent, w, h);
384	  }
385	
386	  // ---------------------------------------------------------------------------
387	  // Empty state helper
388	  // ---------------------------------------------------------------------------
389	
390	  private emptySvg(title: string, message: string, date?: string): string {
391	    const w = this.width;
392	    const h = this.height;
393	    const dateStr = date ?? '';
394	    const svgContent = [
395	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">${title}</text>`,
396	      `  <text class="value" x="${w / 2}" y="${h / 2}" text-anchor="middle">${message}</text>`,
397	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine${dateStr ? ` — ${dateStr}` : ''}</text>`,
398	    ].join('\n');
399	    return wrapSvg(svgContent, w, h);
400	  }
401	}
