1	import { SvgGenerator } from './svg-generator';
2	import type { SvgOptions } from './svg-generator';
3	import { MermaidGenerator } from './mermaid-generator';
4	import { Logger } from '../logger';
5	import type { AggregationStats, TrendAnalysis } from '../schema/types';
6	
7	const log = new Logger('VISUALIZE');
8	
9	export { SvgGenerator, MermaidGenerator };
10	export type { SvgOptions };
11	
12	// =============================================================================
13	// Integration
14	// =============================================================================
15	
16	export interface GeneratedCharts {
17	  topicBarChart: string;
18	  sentimentDonut: string;
19	  trendRadar: string;
20	  eventTimeline: string;
21	}
22	
23	/**
24	 * Convenience function: generate all required charts in one call.
25	 */
26	export function generateAllCharts(
27	  stats: AggregationStats,
28	  trends: TrendAnalysis,
29	  date: string,
30	  options?: SvgOptions,
31	): GeneratedCharts {
32	  log.info(`generateAllCharts invoked for ${date}`);
33	
34	  const svgGen = new SvgGenerator(options);
35	  const mermaidGen = new MermaidGenerator();
36	
37	  return {
38	    topicBarChart: svgGen.generateTopicBarChart(stats.topic_frequency, date),
39	    sentimentDonut: svgGen.generateSentimentDonut(stats.sentiment_distribution, date),
40	    trendRadar: svgGen.generateTrendRadar(trends, date),
41	    eventTimeline: mermaidGen.generateTimeline(stats.top_by_significance, date),
42	  };
43	}
