20	const BARS_DEFAULT = ['#3B82F6', '#6366F1', '#8B5CF6'];
21	const BARS_COLORBLIND = ['#0077BB', '#EE7733', '#009988', '#CC3311', '#33BBEE', '#AA3377', '#BBBBBB'];
22	const SENTIMENT_COLORS_DEFAULT: Record<string, string> = {
23	  positive: '#059669',
24	  neutral: '#6B7280',
25	  negative: '#DC2626',
26	};
27	const SENTIMENT_COLORS_COLORBLIND: Record<string, string> = {
