217	
218	  generateSentimentDonut(
219	    sentimentDistribution: Record<string, number>,
220	    date: string,
221	  ): string {
222	    log.info(`Generating sentiment donut for ${date}`);
223	
224	    const entries = Object.entries(sentimentDistribution);
225	    const total = entries.reduce((s, [, v]) => s + v, 0);
226	
227	    const w = 600;
228	    const h = 500;
229	    const cx = 300;
230	    const cy = 250;
231	    const outerR = 120;
232	    const innerR = 60;
233	
234	    if (total === 0) {
235	      return this.emptySvg(`情感分布 — ${date}`, '暂无情感数据', date);
236	    }
237	
238	    const colors = this.colorScheme === 'colorblind'
239	      ? SENTIMENT_COLORS_COLORBLIND
240	      : SENTIMENT_COLORS_DEFAULT;
241	
242	    // Sort entries for consistent rendering: positive, neutral, negative
243	    const sorted = ['positive', 'neutral', 'negative']
244	      .filter((k) => entries.some(([key]) => key === k))
245	      .map((k) => [k, entries.find(([key]) => key === k)![1]] as [string, number]);
246	
247	    const paths: string[] = [];
248	    const legendItems: string[] = [];
249	
250	    // Start from the top (-90 degrees)
251	    let currentAngle = -90;
252	
253	    sorted.forEach(([key, value], idx) => {
254	      const pct = value / total;
255	      const sweepDeg = pct * 360;
256	      const endAngle = currentAngle + sweepDeg;
257	
258	      const color = colors[key] || '#6B7280';
259	
260	      // Add pattern defs for colorblind
261	      if (this.colorScheme === 'colorblind') {
262	        // Use texture via pattern
263	        paths.push(donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle));
264	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR - 2, outerR + 2, currentAngle, endAngle)}" fill="none" stroke="#333" stroke-width="1" />`);
265	      } else {
266	        paths.push(`  <path d="${donutArcPath(cx, cy, innerR, outerR, currentAngle, endAngle)}" fill="${color}" />`);
267	      }
268	
269	      // Legend
270	      const legendY = 150 + idx * 30;
271	      legendItems.push(`  <rect x="430" y="${legendY}" width="12" height="12" rx="2" fill="${color}" />`);
272	      legendItems.push(`  <text class="label" x="450" y="${legendY + 10}">${SENTIMENT_LABELS[key] || key} (${value})</text>`);
273	
274	      currentAngle = endAngle;
275	    });
276	
277	    const svgContent = [
278	      `  <text class="title" x="${w / 2}" y="40" text-anchor="middle">情感分布 — ${date}</text>`,
279	      paths.join('\n'),
280	      `  <text class="value" x="${cx}" y="${cy - 8}" text-anchor="middle" font-size="24" font-weight="bold" fill="#111827">N=${total}</text>`,
281	      `  <text class="note" x="${cx}" y="${cy + 12}" text-anchor="middle" font-size="12">条</text>`,
282	      legendItems.join('\n'),
283	      `  <text class="note" x="${w / 2}" y="${h - 20}" text-anchor="middle">数据来源: Daily AI Insight Engine — ${date}</text>`,
284	    ].join('\n');
285	
286	    return wrapSvg(svgContent, w, h);
287	  }
